uint32_t mipDim(uint32_t size, uint32_t level)
{
    if (level >= 32)
        return 1;
    uint32_t s = size >> level;
    return s == 0 ? 1 : s;
}

// a*b, returning false on 64-bit overflow
bool mulChecked(uint64_t a, uint64_t b, uint64_t& result)
{
    if (a != 0 && b > UINT64_MAX/a)
        return false;
    result = a*b;
    return true;
}

bool isLittleEndianHost()
{
    const uint16_t one = 1;
    uint8_t first;
    std::memcpy(&first, &one, 1);
    return first == 1;
}

void put32(uint8_t* p, uint32_t v)
{
    for (int i = 0; i < 4; ++i) p[i] = uint8_t(v >> (8*i));
}
void put64(uint8_t* p, uint64_t v)
{
    for (int i = 0; i < 8; ++i) p[i] = uint8_t(v >> (8*i));
}
uint32_t get32(const uint8_t* p)
{
    uint32_t v = 0;
    for (int i = 0; i < 4; ++i) v |= uint32_t(p[i]) << (8*i);
    return v;
}
uint64_t get64(const uint8_t* p)
{
    uint64_t v = 0;
    for (int i = 0; i < 8; ++i) v |= uint64_t(p[i]) << (8*i);
    return v;
}
uint64_t alignUp(uint64_t v, uint64_t a)
{
    return (v + a - 1)/a*a;
}

// Data Format Descriptor for an uncompressed RGBA-family format, identical to
// what libktx generates (KHR Data Format spec 1.3, basic descriptor block)
std::vector<uint32_t> makeDFD(ktx2::Format format)
{
    const ktx2::FormatInfo fi = ktx2::formatInfo(format);
    const uint32_t blockSize = 24 + 16*fi.channels;
    const uint32_t bits = 8*fi.bytesPerChannel;
    std::vector<uint32_t> dfd;
    dfd.reserve(1 + blockSize/4);
    dfd.push_back(4 + blockSize);           // dfdTotalSize
    dfd.push_back(0);                       // vendorId = Khronos, type = basic
    dfd.push_back(2u | blockSize << 16);    // version 1.3, descriptorBlockSize
    dfd.push_back(1u | 1u << 8 | 1u << 16); // RGBSDA, BT709, linear, straight
    dfd.push_back(0);                       // texel block 1x1x1x1
    dfd.push_back(fi.texelSize());          // bytesPlane0
    dfd.push_back(0);                       // bytesPlane4-7
    for (uint32_t c = 0; c < fi.channels; ++c)
    {
        uint32_t channelId = (fi.channels == 4 && c == 3) ? 15u : c; // A = 15
        uint32_t qualifiers = 0;
        uint32_t lower = 0, upper = 0;
        switch (fi.type)
        {
            case ktx2::ComponentType::UNorm:
                upper = bits >= 32 ? 0xFFFFFFFFu : (1u << bits) - 1u;
                break;
            case ktx2::ComponentType::UInt:
                upper = 1;
                break;
            case ktx2::ComponentType::SFloat:
                qualifiers = 0x80u | 0x40u;          // FLOAT | SIGNED
                lower = 0xBF800000u;                 // -1.0f
                upper = 0x3F800000u;                 // +1.0f
                break;
            default:
                break;
        }
        dfd.push_back
        (
            (c*bits) | ((bits - 1) << 16) | ((channelId | qualifiers) << 24)
        );
        dfd.push_back(0);                    // sample position
        dfd.push_back(lower);
        dfd.push_back(upper);
    }
    return dfd;
}

bool validOrientation(const std::string& o, uint32_t dims)
{
    if (o.size() != dims)
        return false;
    if (o[0] != 'r' && o[0] != 'l')
        return false;
    if (dims >= 2 && o[1] != 'u' && o[1] != 'd')
        return false;
    if (dims >= 3 && o[2] != 'i' && o[2] != 'o')
        return false;
    return true;
}

bool validate(const ktx2::Texture& t, std::string& why)
{
    if (!ktx2::formatInfo(t.format).valid())
    {
        why = "unsupported format " + std::to_string(uint32_t(t.format));
        return false;
    }
    if (t.dimensions < 1 || t.dimensions > 3)
    {
        why = "dimensions must be 1, 2 or 3";
        return false;
    }
    if
    (
        t.width == 0 ||
        (t.dimensions >= 2 && t.height == 0) ||
        (t.dimensions == 3 && t.depth == 0)
    )
    {
        why = "width, height and depth must be non-zero";
        return false;
    }
    if (t.faces != 1 && t.faces != 6)
    {
        why = "faces must be 1 or 6";
        return false;
    }
    if (t.faces == 6 && (t.dimensions != 2 || t.width != t.height))
    {
        why = "cube maps must be 2D and square";
        return false;
    }
    if (t.dimensions == 3 && t.layers != 0)
    {
        why = "3D array textures are not allowed";
        return false;
    }
    const uint32_t maxLevels = ktx2::maxLevelCount
    (
        t.width, t.levelHeight(0), t.levelDepth(0)
    );
    if (t.levels.empty() || t.levels.size() > maxLevels)
    {
        why = "level count must be between 1 and " + std::to_string(maxLevels);
        return false;
    }
    for (uint32_t level = 0; level < t.levels.size(); ++level)
    {
        uint64_t expected = t.levelSize(level);
        if (expected == 0 || t.levels[level].size() != expected)
        {
            why = "level " + std::to_string(level) + " holds " +
                std::to_string(t.levels[level].size()) + " bytes, expected " +
                std::to_string(expected);
            return false;
        }
    }
    for (const auto& kv : t.metadata)
    {
        if (kv.first.empty() || kv.first.find('\0') != std::string::npos)
        {
            why = "metadata keys must be non-empty and contain no NUL";
            return false;
        }
    }
    auto o = t.metadata.find("KTXorientation");
    if (o != t.metadata.end() && !validOrientation(o->second, t.dimensions))
    {
        why = "invalid KTXorientation '" + o->second + "' for a " +
            std::to_string(t.dimensions) + "D texture";
        return false;
    }
    return true;
}

// Name of a supercompression scheme id, for error messages
std::string schemeName(uint32_t id)
{
    switch (id)
    {
        case 0 :  return "none";
        case 1 :  return "BasisLZ";
        case 2 :  return "Zstandard";
        case 3 :  return "zlib";
        default : return std::to_string(id);
    }
}

// zstd-compress one mip level. Levels of kMultithreadThreshold bytes or more
// use 'threads' worker threads (0 = all hardware threads)
bool zstdCompress
(
    int level, uint32_t threads, const uint8_t* src, size_t n,
    std::vector<uint8_t>& dst, std::string& why
)
{
    const size_t bound = ZSTD_compressBound(n);
    if (ZSTD_isError(bound))
    {
        why = "level too large for zstd";
        return false;
    }
    dst.resize(bound);
    ZSTD_CCtx* context = ZSTD_createCCtx();
    if (context == nullptr)
    {
        why = "zstd: cannot create a compression context";
        return false;
    }
    ZSTD_CCtx_setParameter(context, ZSTD_c_compressionLevel, level);
    if (n >= kMultithreadThreshold)
    {
        const unsigned workers = threads != 0 ?
            unsigned(threads) : std::thread::hardware_concurrency();
        // If zstd was built without ZSTD_MULTITHREAD this setting is refused
        // and compression simply stays single-threaded
        if (workers > 1)
            ZSTD_CCtx_setParameter
            (
                context, ZSTD_c_nbWorkers, int(std::min(workers, 64u))
            );
    }
    const size_t r = ZSTD_compress2(context, dst.data(), dst.size(), src, n);
    ZSTD_freeCCtx(context);
    if (ZSTD_isError(r))
    {
        why = std::string("zstd: ") + ZSTD_getErrorName(r);
        return false;
    }
    dst.resize(r);
    return true;
}

// Inverse of zstdCompress, into exactly 'expected' bytes at dst
bool zstdDecompress
(
    const uint8_t* src, size_t n, uint8_t* dst, size_t expected,
    std::string& why
)
{
    const size_t r = ZSTD_decompress(dst, expected, src, n);
    if (ZSTD_isError(r))
    {
        why = std::string("zstd: ") + ZSTD_getErrorName(r);
        return false;
    }
    if (r != expected)
    {
        why = "zstd: decompressed size mismatch";
        return false;
    }
    return true;
}

ktx2::Texture makeTexture
(
    ktx2::Format format, uint32_t dims, uint32_t w, uint32_t h, uint32_t d,
    const void* data
)
{
    ktx2::Texture t;
    t.format = format;
    t.dimensions = dims;
    t.width = w;
    t.height = h;
    t.depth = d;
    uint64_t size = t.levelSize(0);
    if (size == 0 || size > SIZE_MAX)
        return t; // Left without levels; write() will report the problem
    t.levels.resize(1);
    if (data != nullptr)
    {
        const uint8_t* p = static_cast<const uint8_t*>(data);
        t.levels[0].assign(p, p + size);
    }
    else
        t.levels[0].assign(size_t(size), 0);
    return t;
}

