using IF = TextureBuffer::InternalFormat;
using ComponentType = ktx2::ComponentType;

ktx2::Format toKtx2Format(IF format)
{
    using KF = ktx2::Format;
    switch (format)
    {
        case IF::R_UNI_8 :    return KF::R8_UNORM;
        case IF::RG_UNI_8 :   return KF::RG8_UNORM;
        case IF::RGBA_UNI_8 : return KF::RGBA8_UNORM;
        case IF::R_UI_8 :     return KF::R8_UINT;
        case IF::RG_UI_8 :    return KF::RG8_UINT;
        case IF::RGBA_UI_8 :  return KF::RGBA8_UINT;
        case IF::R_UI_32 :    return KF::R32_UINT;
        case IF::RG_UI_32 :   return KF::RG32_UINT;
        case IF::RGBA_UI_32 : return KF::RGBA32_UINT;
        case IF::R_SF_32 :    return KF::R32_SFLOAT;
        case IF::RG_SF_32 :   return KF::RG32_SFLOAT;
        case IF::RGBA_SF_32 : return KF::RGBA32_SFLOAT;
        default :             return KF::Undefined; // RGB_*, Undefined
    }
}

IF fromKtx2Format(ktx2::Format format)
{
    using KF = ktx2::Format;
    switch (format)
    {
        case KF::R8_UNORM :      return IF::R_UNI_8;
        case KF::RG8_UNORM :     return IF::RG_UNI_8;
        case KF::RGBA8_UNORM :   return IF::RGBA_UNI_8;
        case KF::R8_UINT :       return IF::R_UI_8;
        case KF::RG8_UINT :      return IF::RG_UI_8;
        case KF::RGBA8_UINT :    return IF::RGBA_UI_8;
        case KF::R32_UINT :      return IF::R_UI_32;
        case KF::RG32_UINT :     return IF::RG_UI_32;
        case KF::RGBA32_UINT :   return IF::RGBA_UI_32;
        case KF::R32_SFLOAT :    return IF::R_SF_32;
        case KF::RG32_SFLOAT :   return IF::RG_SF_32;
        case KF::RGBA32_SFLOAT : return IF::RGBA_SF_32;
        default :                return IF::Undefined; // 64-bit formats
    }
}

// The file's own format if OpenGL can hold it, otherwise (64-bit formats) the
// 32-bit format with the same channels and component type
IF nearestInternalFormat(ktx2::Format format)
{
    IF exact = fromKtx2Format(format);
    if (exact != IF::Undefined)
        return exact;
    const ktx2::FormatInfo info = ktx2::formatInfo(format);
    const bool isFloat = info.type == ComponentType::SFloat;
    switch (info.channels)
    {
        case 1 :  return isFloat ? IF::R_SF_32 : IF::R_UI_32;
        case 2 :  return isFloat ? IF::RG_SF_32 : IF::RG_UI_32;
        case 4 :  return isFloat ? IF::RGBA_SF_32 : IF::RGBA_UI_32;
        default : return IF::Undefined;
    }
}

struct TexelLayout
{
    uint32_t channels = 0;
    uint32_t bytesPerChannel = 0;
    ComponentType type = ComponentType::Invalid;
};

TexelLayout layoutOf(ktx2::Format format)
{
    const ktx2::FormatInfo info = ktx2::formatInfo(format);
    TexelLayout layout;
    layout.channels = info.channels;
    layout.bytesPerChannel = info.bytesPerChannel;
    layout.type = info.type;
    return layout;
}

TexelLayout layoutOf(IF format)
{
    TexelLayout layout;
    layout.channels = TextureBuffer::nChannels(format);
    if (layout.channels == 0)
        throw std::runtime_error("undefined internal format");
    layout.bytesPerChannel =
        TextureBuffer::internalFormatToBytes.at(format)/layout.channels;
    switch (TextureBuffer::internalFormatToDataType.at(format))
    {
        case TextureBuffer::DataType::Float :
            layout.type = ComponentType::SFloat;
            break;
        case TextureBuffer::DataType::UnsignedInt :
            layout.type = ComponentType::UInt;
            break;
        case TextureBuffer::DataType::UnsignedChar :
            layout.type = TextureBuffer::internalFormatToIsUnsigned.at(format) ?
                ComponentType::UInt : ComponentType::UNorm;
            break;
    }
    return layout;
}

// One component as a plain number: 8-bit normalized as its 0-255 code,
// integers as their value, floats as their value
double readComponent(const uint8_t* p, const TexelLayout& layout)
{
    if (layout.type == ComponentType::SFloat)
    {
        if (layout.bytesPerChannel == 8)
        {
            double v;
            std::memcpy(&v, p, 8);
            return v;
        }
        float v;
        std::memcpy(&v, p, 4);
        return v;
    }
    switch (layout.bytesPerChannel)
    {
        case 1 :
            return p[0];
        case 4 :
        {
            uint32_t v;
            std::memcpy(&v, p, 4);
            return v;
        }
        default :
        {
            uint64_t v;
            std::memcpy(&v, p, 8);
            return double(v);
        }
    }
}

// Inverse of readComponent for vir's formats (8-bit normalized, 8/32-bit
// unsigned integers, 32-bit floats). Integer targets round to nearest and
// saturate; NaN becomes 0
void writeComponent(double v, uint8_t* p, const TexelLayout& layout)
{
    if (layout.type == ComponentType::SFloat)
    {
        const double maxFloat = std::numeric_limits<float>::max();
        const float inf = std::numeric_limits<float>::infinity();
        float f = v > maxFloat ? inf : v < -maxFloat ? -inf : float(v);
        std::memcpy(p, &f, 4);
        return;
    }
    const double maxValue = layout.bytesPerChannel == 1 ? 255.0 : 4294967295.0;
    if (!(v > 0.0)) // Also catches NaN
        v = 0.0;
    if (v > maxValue)
        v = maxValue;
    const uint32_t u = uint32_t(v + 0.5);
    if (layout.bytesPerChannel == 1)
        p[0] = uint8_t(u);
    else
        std::memcpy(p, &u, 4);
}

// Factor taking a source value into the target's number range. Only 8-bit
// normalized <-> float changes scale (codes 0-255 <-> 0.0-1.0); every other
// pair keeps the number itself
double rangeScale(ComponentType source, ComponentType target)
{
    if (source == ComponentType::SFloat && target == ComponentType::UNorm)
        return 255.0;
    if (source == ComponentType::UNorm && target == ComponentType::SFloat)
        return 1.0/255.0;
    return 1.0;
}

// Channel count conversion, with the rules stb_image applies when a channel
// count is forced on load. 'one' is a full alpha in the target's range
void mapChannels
(
    const double* s, uint32_t sourceChannels,
    double* d, uint32_t targetChannels,
    double one
)
{
    if (sourceChannels == targetChannels)
    {
        for (uint32_t c = 0; c < targetChannels; ++c)
            d[c] = s[c];
        return;
    }
    const bool sourceIsColor = sourceChannels >= 3;
    const double grey = sourceIsColor ?
        (77.0*s[0] + 150.0*s[1] + 29.0*s[2])/256.0 : // stb's luminance
        s[0];
    const double alpha =
        sourceChannels == 2 ? s[1] : sourceChannels == 4 ? s[3] : one;
    switch (targetChannels)
    {
        case 1 :
            d[0] = grey;
            break;
        case 2 :
            d[0] = grey;
            d[1] = alpha;
            break;
        default : // 3 or 4
            for (uint32_t c = 0; c < 3; ++c)
                d[c] = sourceIsColor ? s[c] : grey;
            if (targetChannels == 4)
                d[3] = alpha;
            break;
    }
}

void convertTexels
(
    const std::vector<uint8_t>& in,
    const TexelLayout& source,
    const TexelLayout& target,
    std::vector<uint8_t>& out
)
{
    const size_t sourceTexel = size_t(source.channels)*source.bytesPerChannel;
    const size_t targetTexel = size_t(target.channels)*target.bytesPerChannel;
    const size_t count = in.size()/sourceTexel;
    const double scale = rangeScale(source.type, target.type);
    const double one = target.type == ComponentType::UNorm ? 255.0 : 1.0;
    out.resize(count*targetTexel);
    double s[4] = {0.0, 0.0, 0.0, 0.0};
    double d[4] = {0.0, 0.0, 0.0, 0.0};
    for (size_t i = 0; i < count; ++i)
    {
        const uint8_t* src = in.data() + i*sourceTexel;
        for (uint32_t c = 0; c < source.channels; ++c)
            s[c] = readComponent(src + c*source.bytesPerChannel, source)*scale;
        mapChannels(s, source.channels, d, target.channels, one);
        uint8_t* dst = out.data() + i*targetTexel;
        for (uint32_t c = 0; c < target.channels; ++c)
            writeComponent(d[c], dst + c*target.bytesPerChannel, target);
    }
}

// Read the base level through the existing typed readData() overloads,
// straight into the (already sized) KTX2 level buffer
template<typename TextureType>
void readBaseLevel(TextureType& texture, std::vector<uint8_t>& bytes)
{
    switch (texture.dataType())
    {
        case TextureBuffer::DataType::UnsignedChar :
        {
            unsigned char* data = bytes.data();
            texture.readData(data, false);
            break;
        }
        case TextureBuffer::DataType::UnsignedInt :
        {
            unsigned int* data = reinterpret_cast<unsigned int*>(bytes.data());
            texture.readData(data, false);
            break;
        }
        case TextureBuffer::DataType::Float :
        {
            float* data = reinterpret_cast<float*>(bytes.data());
            texture.readData(data, false);
            break;
        }
    }
}

template<typename TextureType>
bool encode
(
    TextureType& texture,
    ktx2::Texture&& ktx,
    std::vector<unsigned char>& fileData,
    std::string* error
)
{
    const ktx2::Format format = toKtx2Format(texture.internalFormat());
    if (format == ktx2::Format::Undefined)
        return fail
        (
            error,
            "encodeKtx2 - unsupported internal format " +
            TextureBuffer::internalFormatToName.at(texture.internalFormat())
        );
    ktx.format = format;
    const uint64_t size = ktx.levelSize(0);
    if (size == 0 || size > SIZE_MAX)
        return fail(error, "encodeKtx2 - invalid texture size");
    ktx.levels.assign(1, std::vector<uint8_t>(size_t(size)));
    readBaseLevel(texture, ktx.levels[0]);
    // OpenGL row order: first row is the bottom one
    ktx.metadata["KTXorientation"] = ktx.dimensions == 3 ? "rui" : "ru";
    return ktx2::write(ktx, fileData, ktx2::WriteOptions(), error);
}

